"""Date ranges."""
from datetime import date, timedelta


def _check_step(step):
    if not isinstance(step, int) or isinstance(step, bool) or step < 1:
        raise ValueError("step must be an int of at least 1")


def dates_between(start, end, step=1):
    """The dates from `start` to `end`, every `step` days.

    Forward when ``start <= end``, backward when ``start > end``. ``step`` is
    always a positive number of days. The list includes ``end`` when a step
    lands on it; a step that would pass ``end`` stops the list.
    """
    if not isinstance(start, date) or not isinstance(end, date):
        raise ValueError("start and end must be datetime.date")
    _check_step(step)

    diff = (end - start).days
    if diff == 0:
        return [start]

    count = abs(diff) // step + 1
    if diff > 0:
        return [start + timedelta(days=step * k) for k in range(count)]
    else:
        return [start - timedelta(days=step * k) for k in range(count)]


def count_dates(start, end, step=1):
    """How many dates `dates_between` returns, without building the list."""
    if not isinstance(start, date) or not isinstance(end, date):
        raise ValueError("start and end must be datetime.date")
    _check_step(step)

    diff = (end - start).days
    return abs(diff) // step + 1
